package com.bank.report.repository;

import com.bank.report.model.Trade;
import jakarta.persistence.QueryHint;
import org.springframework.data.jpa.repository.*;
import java.util.List;

public interface TradeRepository extends JpaRepository<Trade, String> {

    // ═══ readOnly hint: skip dirty checking for THIS query only ═══
    @QueryHints(@QueryHint(name = "org.hibernate.readOnly", value = "true"))
    List<Trade> findByAccountIdAndStatus(String accountId, String status);
    // Trades loaded here: NO snapshot, NO dirty checking.
    // Account loaded without hint: HAS dirty checking → update works.

    // ═══ cacheable hint: cache query result in L2 cache ═══
    @QueryHints(@QueryHint(name = "org.hibernate.cacheable", value = "true"))
    List<Trade> findBySymbol(String symbol);
    // First call: SQL. Next calls: cached. No DB hit.

    // ═══ fetchSize hint: efficient for large results ═══
    @QueryHints(@QueryHint(name = "org.hibernate.fetchSize", value = "500"))
    List<Trade> findByStatus(String status);
    // JDBC fetches 500 rows per round-trip. Default: ~10-50.

    // ═══ timeout hint: cancel slow queries ═══
    @QueryHints(@QueryHint(name = "jakarta.persistence.query.timeout", value = "5000"))
    @Query("SELECT t FROM Trade t WHERE t.amount > :min")
    List<Trade> findLargeTradesWithTimeout(@org.springframework.data.repository.query.Param("min") java.math.BigDecimal min);

    // ═══ MULTIPLE hints combined ═══
    @QueryHints({
        @QueryHint(name = "org.hibernate.readOnly", value = "true"),
        @QueryHint(name = "org.hibernate.fetchSize", value = "200")
    })
    List<Trade> findByAccountId(String accountId);
}
