// ─── File: src/main/java/com/bank/report/service/PortfolioReportService.java ───
package com.bank.report.service;

import com.bank.report.dto.ReportResult;
import com.bank.report.model.*;
import com.bank.report.repository.*;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.time.LocalDate;

@Service
@RequiredArgsConstructor
@Slf4j
public class PortfolioReportService {

    private final TradeRepository tradeRepo;
    private final AccountRepository accountRepo;

    // ═══ MIXED TRANSACTION: read trades (readOnly hint) + update account (writable) ═══
    @Transactional  // NOT readOnly! This transaction writes.
    public ReportResult generateReport(String accountId) {

        // Query 1: readOnly hint → 50K trades loaded WITHOUT snapshots
        var trades = tradeRepo.findByAccountIdAndStatus(accountId, "SETTLED");
        // @QueryHints(readOnly=true) → these Trade entities skip dirty checking
        // Memory saved: no snapshot copies for 50K trades

        BigDecimal total = trades.stream()
            .map(Trade::getAmount)
            .reduce(BigDecimal.ZERO, BigDecimal::add);

        // Query 2: NO readOnly hint → Account loaded WITH dirty checking
        Account account = accountRepo.findById(accountId).orElseThrow();
        account.setLastReportDate(LocalDate.now());
        // At flush: Hibernate dirty-checks Account → generates UPDATE
        // Trade entities: NOT dirty-checked (readOnly hint) → no UPDATE generated

        log.info("Report: {} trades, total Rs.{}, account last_report_date updated",
            trades.size(), total);

        return new ReportResult(accountId, trades.size(), total,
            "Trades loaded with @QueryHints(readOnly=true) — no dirty checking. " +
            "Account loaded without hint — update works via dirty checking.");
    }
}
```

